    "content": "在中国人民革命军事博物馆举行的“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”上， 一张借据 的复制品引得人们驻足凝望，借据背后的故事更令观众动容。 这是10月13日在中国人民革命军事博物馆拍摄的湖南汝城发现的红军借据复制件。新华社发（林秋锦摄） 10月13日，在中国人民革命军事博物馆，人们参观湖南汝城发现的红军借据复制件等展品。新华社发（林秋锦摄） 这张土纸借据的原件，纸页泛黄、字迹朴素，被收藏于湖南省郴州市汝城县档案馆之中。它记录着红军长征途中借粮的约定，也记录着红军与当地群众患难相扶、以诚相待的往事…"
