    "description": "据昆明出入境边防检查站统计，截至10月14日，昆明长水国际机场年度入出境外籍人员数量突破100万人次，同比增长18.23%。其中享受免签入境外籍人员达34.86万人次，同比增长16.92%，创历史同期新高。目前，该机场共开通19个国家和地区38个航点，航线网络覆盖南亚、东南亚、东亚等多个区域。 作者：王研、曾维、陈志蓉、王金河 新华社音视频部制作",
