    "title": "国际海事组织秘书长：霍尔木兹海峡通行风险仍高",
    "link": "http://www.news.cn/20261017/cd13aa4bb27342fbab7b94d879288dbf/c.html",
    "pub_date": "2026-10-17 16:16:54",
    "author": "高文成",
    "description": "新华社伦敦10月16日电（记者高文成）国际海事组织秘书长阿塞尼奥·多明格斯16日表示，霍尔木兹海峡及周边海域安全形势持续恶化，船舶通行风险并未降低。他强调，航运不应被用作冲突中的施压工具，冲突各方只有着手解决危机根源，才能为该地区航运安全恢复创造条件。 多明格斯当天在位于英国伦敦的国际海事组织总部接受了新华社记者专访。他表示，国际海事组织过去几个月反复提出的建议没有改变：船舶应避免通过霍尔木兹海峡，避免在相关地区开展贸易活动，并采取措施…",
    "content": "新华社伦敦10月16日电（记者高文成）国际海事组织秘书长阿塞尼奥·多明格斯16日表示，霍尔木兹海峡及周边海域安全形势持续恶化，船舶通行风险并未降低。他强调，航运不应被用作冲突中的施压工具，冲突各方只有着手解决危机根源，才能为该地区航运安全恢复创造条件。 多明格斯当天在位于英国伦敦的国际海事组织总部接受了新华社记者专访。他表示，国际海事组织过去几个月反复提出的建议没有改变：船舶应避免通过霍尔木兹海峡，避免在相关地区开展贸易活动，并采取措施保护海员、船舶和海洋环境。 据国际海事组织官网公布的数据，近期，霍尔木兹海峡及周…"
