    "author": "潘一景,黄玥,田宇",
    "description": "10月16日，习近平总书记来到位于内蒙古自治区乌兰察布市察哈尔右翼前旗的黄旗海自然保护区考察调研。 黄旗海曾是内蒙古渔业基地之一，所产鲫鱼因肉质鲜美而闻名。然而，受气候等影响，黄旗海一度濒临干涸，鱼类失去适宜的生存环境，也逐渐绝迹。经过多年综合治理，水域面积逐步恢复扩大。消失了20多年的鱼类重现，成群水鸟也在此栖息繁衍。 一条小鱼的回归，映照着一片水域的生态之变。跟着总书记的足迹，感悟湖韵新生，见证绿色答卷。 策划：张晓松 监制：朱基钗…",
    "content": "10月16日，习近平总书记来到位于内蒙古自治区乌兰察布市察哈尔右翼前旗的黄旗海自然保护区考察调研。 黄旗海曾是内蒙古渔业基地之一，所产鲫鱼因肉质鲜美而闻名。然而，受气候等影响，黄旗海一度濒临干涸，鱼类失去适宜的生存环境，也逐渐绝迹。经过多年综合治理，水域面积逐步恢复扩大。消失了20多年的鱼类重现，成群水鸟也在此栖息繁衍。 一条小鱼的回归，映照着一片水域的生态之变。跟着总书记的足迹，感悟湖韵新生，见证绿色答卷。 &nbsp; 策划：张晓松 监制：朱基钗 编导：潘一景、黄玥 记者：田宇、严赋憬、张晟、彭源、达日罕、连振…"
