    "description": "10月17日，在晶科2026全球科技日上，晶科能源首席技术官金浩表示，过去20年光伏组件价格累计下降超95%，预计未来5年还将下降50%。他指出，传统降本路径已趋于结束，未来降本将以技术创新、贱金属应用及AI智能化降本为主要驱动力。（界面）",
