    "pub_date": "2026-10-17 15:39:32",
    "author": "刘雅萱,赵旭",
    "description": "二万五千里长征，是惊天动地的革命壮举，是中国共产党和红军谱写的壮丽史诗，是中华民族伟大复兴历史进程中的巍峨丰碑。 中国工农红军长征胜利90周年之际，我们梳理中小学统编教材中的“长征课文”，撷取相关红色地标，制作了一组精美海报。让我们翻开课本，重温长征故事，感悟共产党人的初心和使命，走好新时代的长征路。 策划：钱彤、石锋 监制：令伟家 主创：刘雅萱、朱斯哲 内容支持：人民教育出版社",
    "content": "二万五千里长征，是惊天动地的革命壮举，是中国共产党和红军谱写的壮丽史诗，是中华民族伟大复兴历史进程中的巍峨丰碑。 中国工农红军长征胜利90周年之际，我们梳理中小学统编教材中的“长征课文”，撷取相关红色地标，制作了一组精美海报。让我们翻开课本，重温长征故事，感悟共产党人的初心和使命，走好新时代的长征路。 策划：钱彤、石锋 监制：令伟家 主创：刘雅萱、朱斯哲 内容支持：人民教育出版社"
