    "description": "中国天气网讯 今天(10月17日)大范围雨雪过程将进入最强时段，北方将现同期少见的大范围大到暴雨，局地有大暴雨，内蒙古东北部、黑龙江西北部局地有暴雪或大暴雪。降水的同时，北方多地气温也将刷新今年下半年来新低。一直到下周，冷空气频繁影响我国，北方气温持续偏低，江南等地在经历近期的暖热后，21日前后也将出现降温，秋凉显现。",
