    "author": "南方周末记者 陈相成",
    "description": "泥炭地火灾主要有“深、久、重”三个特点。“‘深’，是指火不只烧地表植被，还烧进泥炭土层；‘久’，是指泥炭火以阴燃为主，扑救难、复燃多，持续时间明显长于一般地表火；‘重’，是指它释放的PM2.5更多，更容易累积并形成跨境烟霾。” 南方周末记者 陈相成 责任编辑：姚忆江 “今年旱季始于6月，8月、9月达到高峰。其间我家附近只下了三场雨，比往年少很多。”印度尼西亚（下称“印尼”）东加里曼丹省洛阿迦南地区的普尔瓦西告诉南方周末记者，“在中加里曼…",
    "content": "泥炭地火灾主要有“深、久、重”三个特点。“‘深’，是指火不只烧地表植被，还烧进泥炭土层；‘久’，是指泥炭火以阴燃为主，扑救难、复燃多，持续时间明显长于一般地表火；‘重’，是指它释放的PM2.5更多，更容易累积并形成跨境烟霾。” 烧荒是印尼多起火灾的重要直接原因。自然状态下的泥炭地含水率高、不易燃烧，但在农业开发、暴露变干后，成为“顽固火源”。 9月下旬至10月上旬，新加坡多区域24小时PSI屡屡升至101以上，较往年同期极为罕见。 南方周末记者 陈相成 责任编辑：姚忆江 “今年旱季始于6月，8月、9月达到高峰。其间…"
